import{_ as o,o as t,c,ag as i}from"./chunks/framework.DNmTgtHf.js";const h=JSON.parse('{"title":"Exception Handling — Exercises","description":"","frontmatter":{},"headers":[],"relativePath":"java/foundations/exceptions/Exercises.md","filePath":"java/foundations/exceptions/Exercises.md"}'),n={name:"java/foundations/exceptions/Exercises.md"};function a(s,e,d,r,l,p){return t(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="exception-handling-—-exercises" tabindex="-1">Exception Handling — Exercises <a class="header-anchor" href="#exception-handling-—-exercises" aria-label="Permalink to &quot;Exception Handling — Exercises&quot;">​</a></h1><hr><h2 id="topic-1-checked-vs-unchecked" tabindex="-1">Topic 1: Checked vs unchecked <a class="header-anchor" href="#topic-1-checked-vs-unchecked" aria-label="Permalink to &quot;Topic 1: Checked vs unchecked&quot;">​</a></h2><p><strong>Exercise 1a — Extend the hierarchy</strong></p><ol><li>Create a checked exception <code>InsufficientFundsException(String message, double shortfall)</code> that stores <code>shortfall</code> as a field with a getter.</li><li>Create an unchecked exception <code>InvalidAccountStateException(String message)</code>.</li><li>Write a method <code>withdraw(double balance, double amount)</code> that: <ul><li>throws <code>InvalidAccountStateException</code> if <code>amount &lt;= 0</code></li><li>throws <code>InsufficientFundsException</code> if <code>amount &gt; balance</code></li><li>prints <code>&quot;Withdrew X&quot;</code> otherwise</li></ul></li><li>In <code>main</code>, call <code>withdraw</code> three times — one success, one invalid amount, one insufficient funds — and handle accordingly.</li></ol><p>Answer in a comment before writing: <strong>Why does <code>InsufficientFundsException</code> need to be checked? Why does <code>InvalidAccountStateException</code> not?</strong></p><hr><h2 id="topic-2-exception-translation" tabindex="-1">Topic 2: Exception translation <a class="header-anchor" href="#topic-2-exception-translation" aria-label="Permalink to &quot;Topic 2: Exception translation&quot;">​</a></h2><p><strong>Exercise 2a</strong></p><p>Write a method <code>loadUserConfig(String filename)</code> that:</p><ul><li>internally calls a helper <code>readFile(String filename)</code> which throws a simulated checked <code>java.io.IOException</code></li><li><code>loadUserConfig</code> must NOT declare <code>throws IOException</code> on its signature</li><li>translates the low-level <code>IOException</code> into a domain <code>ConfigLoadException</code> (unchecked), <strong>preserving the original cause</strong></li></ul><p>In <code>main</code>, call <code>loadUserConfig(&quot;missing.cfg&quot;)</code> and print <code>ex.getCause().getClass().getSimpleName()</code> to confirm the cause is preserved.</p><hr><h2 id="topic-3-try-with-resources" tabindex="-1">Topic 3: try-with-resources <a class="header-anchor" href="#topic-3-try-with-resources" aria-label="Permalink to &quot;Topic 3: try-with-resources&quot;">​</a></h2><p><strong>Exercise 3a — Warm-up (close ordering)</strong></p><p>Create a class <code>Resource</code> that implements <code>AutoCloseable</code>:</p><ul><li>constructor prints <code>&quot;Opening Resource [name]&quot;</code></li><li><code>use()</code> prints <code>&quot;Using Resource [name]&quot;</code></li><li><code>close()</code> prints <code>&quot;Closing Resource [name]&quot;</code></li></ul><p>Open two resources in a single <code>try-with-resources</code> block (<code>r1</code> and <code>r2</code>). Call <code>use()</code> on both.</p><p>Note in a comment: <strong>which closes first, and why?</strong></p><p><strong>Exercise 3b — Close with exception</strong></p><p>Extend <code>Resource.close()</code> to throw <code>RuntimeException(&quot;Close failed: [name]&quot;)</code> for <code>r1</code> only. In <code>main</code>:</p><ul><li>call <code>r1.use()</code>, then throw <code>RuntimeException(&quot;Body failed&quot;)</code> from the try body</li><li>catch the exception, print <code>ex.getMessage()</code>, then print <code>ex.getSuppressed()[0].getMessage()</code></li></ul><p>Predict what you&#39;ll see before running. Note in a comment: <strong>why is the body exception primary and the close exception suppressed?</strong></p>',23)])])}const g=o(n,[["render",a]]);export{h as __pageData,g as default};
